examples.code:
{ "id": "stage/runner", "kind": "push", "timeout": "10m",
  "push": {
    "sha256": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
    "dest": "/data/local/tmp/farm/run_soak.sh",
    "mode": "0755" } }

{ "id": "stage/app", "kind": "install", "timeout": "10m",
  "install": {
    "sha256": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
    "reinstall": true,
    "grant": true } }

{ "id": "soak/start", "kind": "shell_detached", "timeout": "2m",
  "shell_detached": {
    "command": "sh /data/local/tmp/farm/run_soak.sh",
    "result_path": "/data/local/tmp/farm/soak.result",
    "handle": "soak" } }

{ "id": "idle/await", "kind": "wait_for", "timeout": "6h",
  "wait_for": {
    "probe": "[ \"$(dumpsys deviceidle get deep)\" = \"IDLE\" ]",
    "interval": "30s",
    "timeout": "5h59m" } }

{ "id": "collect/logcat", "kind": "pull", "timeout": "10m",
  "pull": {
    "path": "/data/local/tmp/farm/logcat.txt",
    "artifact": "logcat.txt" } }

